1	/**
2	*
3	* # OTEL Collector (K8s Addon)
4	* Deploys otel collector via terraform.
5	* ## Created Resources
6	* 1. otel collector.
7	*
8	*/
9	terraform {
10	  required_version = ">= 1.3.0"
11	
12	  required_providers {
13	    helm = {
14	      source  = "hashicorp/helm"
15	      version = "~> 2.0"
16	    }
17	    kubernetes = {
18	      source  = "hashicorp/kubernetes"
19	      version = "~> 2.0"
20	    }
21	  }
22	}
23	
24	resource "kubernetes_namespace" "this" {
25	  metadata {
26	    name = var.namespace
27	
28	    #labels = merge(var.tags, { "sourceModule" = "/internal-modules/kubernetes/monitoring/otel-collector" })
29	
30	    annotations = var.annotations
31	  }
32	}
33	
34	resource "kubernetes_manifest" "otel-collector" {
35	  count = var.downstream_endpoint == "" ? 1 : 0
36	
37	  manifest = {
38	    "apiVersion" = "external-secrets.io/v1"
39	    "kind"       = "ExternalSecret"
40	    "metadata" = {
41	      "name"      = "otel-collector"
42	      "namespace" = var.namespace
43	    }
44	    "spec" = {
45	      "refreshInterval" = "1h0m0s"
46	      "secretStoreRef" = {
47	        "name" = "vault"
48	        "kind" = "ClusterSecretStore"
49	      }
50	      "target" = {
51	        "name"           = "otel-collector"
52	        "creationPolicy" = "Owner"
53	      }
54	      "data" = [
55	        {
56	          "secretKey" = "DD_API_KEY"
57	          "remoteRef" = {
58	            "key"      = "secret/data/saas/infrastructure/datadog-api-key"
59	            "property" = "apiKey"
60	          }
61	        },
62	      ]
63	    }
64	  }
65	  depends_on = [kubernetes_namespace.this]
66	}
67	
68	
69	resource "helm_release" "otel_collector_lb" {
70	  #name      = var.name
71	  name             = "otel-collector-lb"
72	  namespace        = var.namespace
73	  create_namespace = false
74	  repository       = "https://open-telemetry.github.io/opentelemetry-helm-charts/"
75	  chart            = "opentelemetry-collector"
76	  version          = var.chart_version
77	
78	  values = [yamlencode({
79	    mode = "deployment"
80	    image = {
81	      repository = var.otellb_image
82	      tag        = var.image_tag_version
83	    }
84	    replicaCount = var.otel_lb_replicas
85	
86	    nameOverride = "collector"
87	
88	    annotations = var.annotations
89	
90	    podLabels = {
91	      "ic-ops.net/otel"           = "collector"
92	      "app.kubernetes.io/part-of" = "opentelemetry-collector"
93	    }
94	
95	    #serviceAccount = {
96	    #  create = true,
97	    #  name   = var.otellb_sa_name,
98	    #  annotations = var.sa_annotations
99	    #}
100	
101	    presets = {
102	      # enables the k8sattributesprocessor and adds it to the traces, metrics, and logs pipelines
103	      kubernetesAttributes = {
104	        enabled                  = true
105	        extractAllPodLabels      = false
106	        extractAllPodAnnotations = true
107	      }
108	    }
109	
110	    serviceAccount = {
111	      create      = true,
112	      name        = var.otellb_sa_name
113	      annotations = var.sa_annotations
114	    }
115	
116	    command = {
117	      extraArgs = var.otellb_extra_args
118	    }
119	
120	    ports = {
121	      otlp = {
122	        enabled       = true
123	        containerPort = 4317
124	        servicePort   = 4317
125	        protocol      = "TCP"
126	        appProtocol   = "grpc"
127	      }
128	      otlp-http = {
129	        enabled       = true
130	        containerPort = 4318
131	        servicePort   = 4318
132	        protocol      = "TCP"
133	      }
134	      jaegar-compact = {
135	        enabled = false
136	      }
137	      jaeger-grpc = {
138	        enabled = false
139	      }
140	      jaeger-thrift = {
141	        enabled = false
142	      }
143	      zipkin = {
144	        enabled = false
145	      }
146	    }
147	
148	    config = local.lb_config
149	  })]
150	
151	  depends_on = [
152	    kubernetes_namespace.this,
153	    kubernetes_manifest.otel-collector,
154	    helm_release.otel_collector_processor
155	  ]
156	}
157	
158	resource "helm_release" "otel_collector_processor" {
159	  #name      = var.name
160	  name             = "otel-collector-processor"
161	  namespace        = var.namespace
162	  create_namespace = false
163	  repository       = "https://open-telemetry.github.io/opentelemetry-helm-charts/"
164	  chart            = "opentelemetry-collector"
165	  version          = var.chart_version
166	
167	  values = [yamlencode({
168	    mode = "statefulset"
169	    image = {
170	      repository = var.otel_image
171	      tag        = var.image_tag_version
172	    }
173	    statefulset = {
174	      persistentVolumeClaimRetentionPolicy = {
175	        enabled     = true
176	        whenDeleted = "Delete"
177	        whenScaled  = "Delete"
178	      }
179	
180	      volumeClaimTemplates = [
181	        {
182	          metadata = {
183	            name = "otel-collector-data"
184	          }
185	          spec = {
186	            accessModes = ["ReadWriteOnce"]
187	            resources = {
188	              requests = {
189	                storage = var.otel_pv_size
190	              }
191	            }
192	            //storageClassName = var.otel_storage_class_name
193	          }
194	        }
195	      ]
196	    }
197	
198	    extraVolumeMounts = [{
199	      name      = "otel-collector-data"
200	      mountPath = "/var/lib/storage/queue"
201	    }]
202	
203	    initContainers = [{
204	      name    = "init-fs"
205	      image   = "busybox:latest"
206	      command = ["sh", "-c", "chown -R 10001: /var/lib/storage/queue"]
207	      volumeMounts = [{
208	        name      = "otel-collector-data"
209	        mountPath = "/var/lib/storage/queue"
210	      }]
211	    }]
212	
213	    nameOverride = "processor"
214	
215	    replicaCount = var.otel_collector_replicas
216	
217	    service = {
218	      type      = "ClusterIP"
219	      clusterIP = "None" # Headless service for statefulset
220	    }
221	
222	    annotations = var.annotations
223	    podLabels = {
224	      "ic-ops.net/otel"           = "processor"
225	      "app.kubernetes.io/part-of" = "opentelemetry-collector"
226	    }
227	
228	    serviceAccount = {
229	      create      = true,
230	      name        = var.otel_sa_name,
231	      annotations = var.sa_annotations
232	    }
233	
234	    command = {
235	      extraArgs = var.extra_args
236	    }
237	
238	    extraEnvsFrom = var.downstream_endpoint == "" ? [{
239	      secretRef = {
240	        name = "otel-collector"
241	      }
242	    }] : []
243	
244	    #presets = {
245	    # enables the k8sattributesprocessor and adds it to the traces, metrics, and logs pipelines
246	    #kubernetesAttributes = {
247	    #  enabled = true
248	    #  extractAllPodLabels = true
249	    #  extractAllPodAnnotations = true
250	    #}
251	    #}
252	
253	    ports = {
254	      otlp = {
255	        enabled       = true
256	        containerPort = 4317
257	        servicePort   = 4317
258	        protocol      = "TCP"
259	        appProtocol   = "grpc"
260	      }
261	      otlp-http = {
262	        enabled       = true
263	        containerPort = 4318
264	        servicePort   = 4318
265	        protocol      = "TCP"
266	      }
267	      jaegar-compact = {
268	        enabled = false
269	      }
270	      jaeger-grpc = {
271	        enabled = false
272	      }
273	      jaeger-thrift = {
274	        enabled = false
275	      }
276	      zipkin = {
277	        enabled = false
278	      }
279	    }
280	
281	    config = local.otel_config
282	  })]
283	
284	  depends_on = [
285	    kubernetes_namespace.this,
286	    kubernetes_manifest.otel-collector
287	  ]
288	
289	  lifecycle {
290	    create_before_destroy = false
291	  }
292	}
293	
294	module "netpol" {
295	  source = "git@gitlab.infrastructure.immuta.io:infrastructure/terraform/internal-modules/kubernetes/security/network-policy.git?ref=v1.1.0"
296	
297	  name             = join("-", [var.name, "netpol"])
298	  namespace        = var.namespace
299	  network_policies = local.netpols
300	
301	  tags = merge(var.tags, { "sourceModule" = "/internal-modules/kubernetes/monitoring/otel-collector" })
302	
303	  depends_on = [
304	    kubernetes_namespace.this
305	  ]
306	}
